# -*- coding: utf-8 -*-
"""data_proj_cards_f.py —— ㉓ SSD1306 OLED 显示（I2C）流程卡"""

FLOW_P23_OLED = r"""{m:"流程", t:"flow", n:"㉓ SSD1306 OLED 显示（I2C）", d:"一块 128×64 单色 OLED 挂在 I2C1 上（SCL=PB8 / SDA=PB9，与 24C02、MPU6050 共总线），解决“设备独立运行时人眼什么都看不见”的问题。全部绘制先写 1024 字节显存、最后整帧一次性推屏；本卡讲清三件最容易出错的事：控制字节 0x00/0x40 不能混、页寻址的位序是低位在上、整帧刷新必须一次性持锁（板2 一帧 40 次独立 I2C 事务，中途被 MPU6050/24C02 插进来就是撕裂）。同时如实说明：两个 OLED 驱动目前全工程没有任何调用者，卡里给出接进 FreeRTOS 任务的最小示例。",
 f:[["接线、供电与地址先钉死","四线模块 VCC/GND/SCL/SDA：VCC 接 3.3V，模块板载电荷泵自己产生屏需要的高压，不需要外部升压；SCL=PB8、SDA=PB9，与板载 24C02、MPU6050 共用 I2C1，板载已有 4.7k 上拉，插排针即可。7 位地址默认 0x3C（模块背面 SA0 上拉时是 0x3D）；模块背面标的 0x78/0x7A 是含读写位的 8 位形式，右移一位才是 0x3C。","上拉缺失时现象最迷惑：SYS_I2C_Scan 能扫到 0x3C，但一刷屏就丢字节、偶发花屏，先分开验证“通不通”和“写得进写不进”"],
   ["先开总线，再谈屏（顺序不能反）","SSD1306 驱动建在 sys_i2c 之上，它自己不管 GPIO、不管时钟分频。上电后必须先 SYS_I2C_Init(bus, 400000)（板2 的总线号宏是 OLED_I2C_ID = SYS_I2C_1），再 OLED_Init() / SYS_OLED_Init(bus, addr)；反之，屏初始化时总线还不存在，所有事务以超时结束。速率要给足 400kHz：整屏 1024 字节在 100kHz 下约 90ms，400kHz 下约 23~25ms。","SYS_I2C_Scan(bus, list, max) 可以先确认 0x3C 在不在总线上，返回的是扫到的器件个数，比盲猜地址快得多"],
   ["控制字节：0x00 全是指令，0x40 全是数据","每笔 I2C 事务的第一个字节是控制字节，它告诉 SSD1306 后面的字节是什么：0x00 = 后面全是指令；0x40 = 后面全是显存数据。板2 源码里 oled_cmd / oled_cmd2 走 0x00，刷屏数据走 0x40（oled_wr(0x40U, &oled_buf[p][off], n)）。它必须和它管辖的那批字节放在同一笔事务里，单独发一个控制字节会被屏当成结束。","“写进去没反应”“屏亮了但内容不变”最常见的原因就是控制字节混用：把显存数据用 0x00 发出去，屏会当指令解析，不但不显示还可能把配置改乱"],
   ["初始化序列按序执行，重点是电荷泵那一项","板2 oled.c 的 OLED_Init 顺序（逐条对应手册）：0xAE 关显示 → 0xD5,0x80 时钟 → 0xA8,0x3F 复用率 64 行 → 0xD3,0x00 显示偏移 → 0x40 起始行 0 → 0x8D,0x14 电荷泵开 → 0x20,0x00 寻址模式（页模式，配合逐页写）→ 0xA1 段重映射 → 0xC8 扫描方向 → 0xDA,0x12 COM 配置 → 0x81,0xCF 对比度 → 0xD9,0xF1 预充电 → 0xDB,0x40 VCOMH → 0xA4 跟随显存 → 0xA6 正常显示（非反相）→ 0x2E 关滚动 → 清显存并刷一次 → 0xAF 开显示。","0x8D,0x14 漏掉或参数据写成 0x10（关），屏全黑，但地址扫得到、错误计数还是 0，极容易被误判成坏屏。初始化期间整段持锁，失败不中断（屏可能后插上）"],
   ["页寻址：像素 (x,y) 存在 buf[x + (y/8)*128]，低位在上","128 列 × 8 页 × 每页 8 位 = 1024 字节。屏不是按行存的，是按页存的：页号 = y/8，页内位号 = y%8，而这个字节的 bit0 是这一页最上面那一行、bit7 是最下面，也就是“低位在上”。板2 源码里缓冲是二维 static uint8_t oled_buf[OLED_PAGE_CNT][OLED_WIDTH]，oled_buf[p][x] 与一维写法 x + p*128 完全等价。","把位序按“高位在上”理解，画出来的图形会上下镜像；把一维下标写成 y*128+x（按行存），整幅图会撕裂成斜条。画完用 OLED_GetPoint(x, y) 读回来比对，是最快的自检"],
   ["画图只改内存，OLED_Refresh 才是唯一的“显形”动作","ClearBuffer / DrawPoint / DrawHLine / DrawVLine / DrawLine / DrawRect / FillRect / DrawCircle / ShowProgress / ShowChar / ShowString / ShowStringCenter / ShowNum / ShowFixed 全部只动 RAM，屏上此刻没有任何变化；只有 OLED_Refresh() 把显存推上屏。这正是“先拼帧、再一次上屏”的意义：一屏内容瞬间整体替换，看不到闪烁和半新半旧。","这些纯绘图函数也取锁，用于避免与 OLED_Refresh 并发。否则刷新推到一半显存被改，屏上就是“半新半旧”。改了内存忘记调 Refresh，是“改了没反应”的第一嫌疑"],
   ["整帧刷新必须一次性持锁（板2 是 40 次事务）","板2 OLED_Refresh() 的写法是逐页写：每页先发 3 条定位命令（0xB0|页号、列低 4 位、列高 4 位，合并成一笔事务），再把 128 字节分 4 块 ×32 字节发出去；8 页合计 40 次独立 I2C 事务。源码用 OLED_FRAME_LOCK() / OLED_FRAME_UNLOCK()（就是 SYS_I2C_Lock(OLED_I2C_ID) / Unlock）把整段包住。板1 的 SYS_OLED_Refresh 同理，整帧一笔 1024 字节也照样持锁。","锁是“每条总线一把递归互斥量”，同任务重入只加计数、不会自锁死，所以“外层包整帧 + 内层公共函数各自加锁”可以安全嵌套。代价必须讲清楚：刷屏期间这把锁一直被持有，MPU6050 采数、24C02 读写想用总线就得等 20ms 量级，这是“整帧不可插入”的必然代价，不是实现缺陷"],
   ["接进 FreeRTOS：驱动写好了，但全工程没人调用","如实说明：OLED_Init 只在板2 oled.c:101 定义、SYS_OLED_Init 只在板1 sys_oled.c:259 定义，两板 main.c 与各任务里找不到任何调用者，屏插上去不亮不是模块坏了，是没人叫它干活。正确接法是新建一个显示任务：先 SYS_I2C_Init 开总线，再 OLED_Init()，然后 100ms 一帧“拼帧 + OLED_Refresh()”。任务优先级放在采样任务之后（损失一帧没人受伤，丢一拍采样才要紧），栈 256 字足够。","绝不能把刷屏塞进 1ms 定时器中断：一帧 20ms 以上，等于吃掉二十几个 tick；而且 sys_i2c 在中断上下文里会跳过加锁，等于没有互斥。屏也应当只有一个“主人”任务，两个任务同时刷会互相踩显存"],
   ["想更快：总线提速 / 换 SPI / 只刷脏页","三条正路：① 总线从 100kHz 提到 400kHz（板2 的 OLED_Init 依赖调用方先 SYS_I2C_Init(…, 400000)）；② 换 SPI 版 SSD1306，同样 1024 字节在 10MHz 量级下不到 1ms，且不用和别的器件抢总线；③ 只刷变化了的页（脏页刷新），把 8 页里改过的 1~2 页挑出来单独发，持锁时间从 20ms 降到 3~5ms。","脏页刷新的代价是要自己维护一份“哪几页脏”的标记；本项目两板都是全帧刷新，先把 100ms 的刷新周期跑通，再去谈优化"],
   ["用错误计数把故障空间一刀切两半","屏不亮时先看 OLED_ErrCount() / SYS_OLED_ErrCount()：计数在涨 = 写不进去（接线、上拉、地址、总线被占）；计数为 0 却仍不亮 = 通信是通的，问题在屏本身、供电或对比度。OLED_LastErr() / SYS_OLED_LastErr() 给出最近一次失败的 SYS_I2C 错误码，OLED_IsOnline() 只回答“地址上有没有人应答”。","“能寻址”不等于“写得进去”：上拉不足或走线过长时 OLED_IsOnline() 仍返回 1，而 Refresh 一路失败，判断写没写进去，只认错误计数。OLED_Refresh 返回的是写失败的页数（0 = 8 页全成功），可以据此降级"]
  ],
 a:[["器件与规格","SSD1306 · 128×64 单色 · I2C 接口 · 模块板载电荷泵，3.3V 直接可用","板2 宏：OLED_WIDTH=128 / OLED_HEIGHT=64 / OLED_PAGE_CNT=8；板1 对应 SYS_OLED_WIDTH/HEIGHT/PAGES"],
   ["7 位从机地址","0x3C（模块背面 SA0 上拉时 0x3D）","板2 #define OLED_ADDR 0x3C；板1 SYS_OLED_I2C_ADDR = SYS_I2C_ADDR_SSD1306 = 0x3C；手册标的 0x78/0x7A 是 8 位形式"],
   ["总线与引脚","SYS_I2C_1（板2 宏 OLED_I2C_ID）· SCL=PB8 · SDA=PB9","与板载 24C02(0x50)、MPU6050(0x68) 共用；板载已有 4.7k 上拉"],
   ["控制字节","0x00 = 后面全是指令 · 0x40 = 后面全是显存数据","每笔事务的第一个字节；它和被管辖的字节必须在同一笔事务里。混用 = 写进去没反应"],
   ["显存映射","像素 (x,y) 存在 buf[x + (y/8)*128]，取该字节第 y%8 位，低位在上（0x01 是最上面那一行）","板2 实为 oled_buf[8][128]，与一维写法等价；位序理解反了图形上下镜像"],
   ["初始化关键项","0x8D,0x14 = 电荷泵开（必须）· 0x20,0x00 = 页寻址模式 · 0x81,0xCF = 对比度 · 0xA6 = 正常显示 · 0xAF = 开显示","板2 oled.c:101 的 OLED_Init 里逐条对应手册；漏 0x8D,0x14 屏全黑而错误计数仍为 0"],
   ["整帧刷新开销","板2：8 页 × (1 条定位 + 4 块×32 字节) = 40 次独立 I2C 事务，整屏约 23~25ms @400kHz","板1：一笔事务发 1024 字节，语义相同。失败时因重试 3 次 + I2C 超时，最坏放大到数百毫秒"],
   ["总线锁","OLED_FRAME_LOCK() / UNLOCK() = SYS_I2C_Lock(OLED_I2C_ID) / SYS_I2C_Unlock(OLED_I2C_ID)","每总线一把递归互斥量，同任务可重入可嵌套；包住整帧，否则 MPU6050/24C02 插进来就撕裂"],
   ["分块与重试","OLED_CHUNK = 32 字节 / 页内分块发 · OLED_RETRY = 3 次自动重试","SSD1306 单次写不能跨页；失败重试后仍失败才累加 OLED_ErrCount() 并记 OLED_LastErr()"],
   ["板2 API（oled.c/.h，UTF-8）","OLED_Init / IsOnline / ErrCount / LastErr / ErrClear / ClearBuffer / Refresh / Clear / DisplayOn / DisplayOff / SetContrast / DrawPoint / GetPoint / InvertScreen / DrawHLine / DrawVLine / DrawLine / DrawRect / FillRect / DrawCircle / ShowProgress / ShowChar / ShowString / ShowStringCenter / ShowNum / ShowFixed","定位是“像素坐标 + 反显标志”：ShowChar(x,y,ch,inv) / ShowString(x,y,str,inv) / ShowNum(x,y,num,len,inv) / ShowFixed(x,y,val,frac,int_len,inv) / ShowStringCenter(y,str,inv)，inv=1 是白底黑字"],
   ["板1 API（sys_oled.c/.h，GBK）","SYS_OLED_Init(bus,addr) / Clear / Refresh / ShowChar / ShowString / ShowNum / ShowFloat / SetPixel / ShowBitmap / DisplayOn / DisplayOff / ErrCount / LastErr / ErrClear","定位是“页号 0~7 + 列”：ShowChar(page,x,ch) / ShowString(page,x,str) / ShowNum(page,x,num) / ShowFloat(page,x,value,dec) / SetPixel(x,y,on) / ShowBitmap(page,x,bmp,w,h)。同一块屏、另一套板级封装，函数名与形参完全不同"]],
 e:"/* ============================================================\n *  SSD1306 OLED 显示（I2C），从开总线到整帧刷新的完整可用代码\n *  平台：STM32F407 · FreeRTOS · SSD1306 128x64 单色 OLED\n *  总线：SYS_I2C_1（SCL=PB8 / SDA=PB9），与 24C02、MPU6050 共用\n *  板级 API 两套（同一块屏）：\n *    板2  oled.c/.h（UTF-8）: OLED_*      , 像素坐标 + 反显标志 inv\n *    板1  sys_oled.c/.h（GBK）: SYS_OLED_*, 页号 page(0~7) + 列 x\n *  本例以板2 的 OLED_* 为准（板1 对照见下方注释）\n * ============================================================ */\n#include \"stm32f4xx.h\"\n#include \"oled.h\"           /* 板级配置：总线号 / 地址 / 分辨率都在这个头里 */\n#include \"sys_i2c.h\"        /* I2C1 初始化、总线锁、器件探测 */\n#include \"FreeRTOS.h\"\n#include \"task.h\"\n\n/* ---------------- ① 地址自检：先确认“总线上有人” ---------------- */\nstatic uint8_t oled_selfcheck(void)\n{\n    uint8_t list[8];\n    uint8_t n;\n\n    /* SYS_I2C_Scan 逐个地址探测，返回扫到的器件个数并把地址填进 list。\n     * 它比盲试地址快得多：扫一遍就知道屏在不在、是不是意外的 0x3D。 */\n    n = SYS_I2C_Scan(OLED_I2C_ID, list, 8U);\n    if (n == 0U) {\n        return 0U;              /* 一个器件都没有：查供电、查 PB8/PB9 接线 */\n    }\n\n    /* IsDeviceReady 只回答“这个地址有没有人应答”。\n     * 能寻址不等于写得进去，上拉不足 / 走线过长时，\n     *   它能返回在线，但 OLED_Refresh 会一路失败。所以下面还要看错误计数。 */\n    if (SYS_I2C_IsDeviceReady(OLED_I2C_ID, OLED_ADDR) != SYS_I2C_OK) {\n        /* 默认 0x3C 没应答：模块背面 SA0 被上拉时地址是 0x3D，试一下 */\n        if (SYS_I2C_IsDeviceReady(OLED_I2C_ID, 0x3DU) != SYS_I2C_OK) {\n            return 0U;          /* 两个地址都没人：屏没插好 / 没供电 */\n        }\n        /* 走到这里说明屏在 0x3D：把 oled.h 里的 OLED_ADDR 改成 0x3D 再编 */\n    }\n    return 1U;\n}\n\n/* ---------------- ② 初始化：先开总线，再初始化屏 ---------------- */\nstatic uint8_t oled_boot(void)\n{\n    /* 顺序不能反：驱动建在 sys_i2c 之上，总线没起来时所有事务都超时。\n     * 400kHz 是 SSD1306 支持的速率，整屏 1024 字节约 23~25ms；\n     * 留在 100kHz 就要 90ms 量级，刷屏发顿十有八九是这里没提速。 */\n    SYS_I2C_Init(OLED_I2C_ID, 400000);\n\n    /* OLED_Init() 内部按手册发完整上电序列，其中最关键的是\n     * 0x8D,0x14 电荷泵开，漏了或参数写成 0x10，屏全黑，\n     * 但地址照样扫得到、错误计数还是 0，最容易被误判成坏屏。\n     * 它也把 0x20,0x00（页寻址模式）定下来，配合下面的逐页写。 */\n    OLED_Init();\n\n    if (oled_selfcheck() == 0U) {\n        return 0U;\n    }\n    /* 初始化阶段（调度器未启动）加锁是空操作，本来就没有并发 */\n    return 1U;\n}\n\n/* ---------------- ③ 拼一帧：所有绘制只改显存 ---------------- */\nstatic void oled_draw_page(float temp_c, float humi_rh, uint32_t cnt)\n{\n    int32_t t100 = (int32_t)(temp_c * 10.0f);   /* 25.43 -> 254，定点交给 ShowFixed */\n    int32_t h10  = (int32_t)(humi_rh * 10.0f);  /* 61.0  -> 610 */\n\n    /* ClearBuffer 只清 RAM，屏上此刻没有任何变化；\n     * 要清屏并立刻推上去就用 OLED_Clear()（它内部会再刷一次）。 */\n    OLED_ClearBuffer();\n\n    /* 8x16 点阵：一行 16 个字符、共 4 行。inv=0 黑底白字，inv=1 白底黑字 */\n    OLED_ShowStringCenter(0, \"NODE-2 COMM\", 0);\n\n    /* 定宽显示：位数变化时后面的内容不会被挤走，读数原地刷新不跳动。\n     *   ShowFixed(x, y, val, frac, int_len, inv)：val 是放大后的整数。\n     *   例：val=254, frac=1 -> 显示 25.4；int_len 是整数部分宽度。 */\n    OLED_ShowString(0, 16, \"T=\", 0);\n    OLED_ShowFixed(16, 16, t100, 1U, 3U, 0);\n    OLED_ShowString(64, 16, \"C\", 0);\n\n    OLED_ShowString(0, 32, \"H=\", 0);\n    OLED_ShowFixed(16, 32, h10, 1U, 3U, 0);\n    OLED_ShowString(64, 32, \"%\", 0);\n\n    OLED_ShowNum(0, 48, cnt, 6U, 0);            /* 定宽 6 位无符号整数 */\n\n    /* 图形接口同样只改 RAM：画框 + 进度条（permille 0~1000） */\n    OLED_DrawRect(0, 0, 127, 63, 1);\n    OLED_ShowProgress(8, 56, 112, 6, 700U);     /* 70% 进度条 */\n}\n\n/* ---------------- ④ 上屏：整帧一次性持锁 ---------------- */\nstatic uint8_t oled_push(void)\n{\n    uint8_t fail;\n\n    /* OLED_Refresh 内部就是：OLED_FRAME_LOCK() -> 8 页逐页写\n     *   （每页 1 条定位命令 + 4 块 32 字节）-> OLED_FRAME_UNLOCK()。\n     *   一帧共 40 次独立 I2C 事务，整段在同一个临界区里。\n     *   为什么必须这样：I2C1 上还有 MPU6050(0x68) 和 24C02(0x50)，\n     *   刷到一半被插进来就是“半屏新、半屏旧”的撕裂。\n     *   代价：这 20ms 量级里别的器件要等，这是整帧不可插入的必然代价。\n     *   返回：0 = 8 页全成功；>0 = 写失败的页数（1~8），据此降级。 */\n    fail = OLED_Refresh();\n    return fail;\n}\n\n/* ---------------- ⑤ 显示任务：接进 FreeRTOS 的最小示例 ---------------- */\n/* 事实：两板 OLED 驱动都写好了，但全工程没有调用者，\n *   板2 OLED_Init 只在 oled.c:101 定义，板1 SYS_OLED_Init 只在\n *   sys_oled.c:259 定义，main.c 里没有接。屏不亮不是模块坏了，\n *   是没人叫它干活（可用 grep 搜 OLED_Init / SYS_OLED_Init 自己确认）。建任务：\n *     xTaskCreate(vOledTask, \"oled\", 256, 0, 3, 0);\n *   优先级放在采样任务之后（掉一帧没人受伤，丢一拍采样才要紧），\n *   栈 256 字足够：这里只有定点转换和 I2C 调用，没有深递归。 */\nvoid vOledTask(void *pv)\n{\n    uint8_t  oled_ok;\n    uint32_t cnt = 0U;\n    float    temp = 25.4f;      /* 换成自己的传感器读数 */\n    float    humi = 61.0f;\n\n    (void)pv;\n\n    oled_ok = oled_boot();\n\n    for (;;) {\n        if (oled_ok != 0U) {\n            oled_draw_page(temp, humi, cnt);\n\n            /* 上屏失败就降级：错误计数在涨说明“写不进去”\n             *（接线 / 上拉 / 地址 / 总线被占），计数为 0 却仍不亮\n             * 就是屏本身、供电或对比度的问题，一刀把故障切两半。 */\n            if (oled_push() != 0U) {\n                if (OLED_ErrCount() >= 10U) {\n                    oled_ok = 0U;   /* 反复写不进去就别再刷，免得拖慢总线 */\n                }\n            }\n            cnt++;\n        }\n\n        /* 100ms 一帧：人眼够顺，总线占用也低。\n         *   绝不能塞进 1ms 定时器中断，一帧 20ms 以上会吃掉二十几个 tick，\n         *   而且 sys_i2c 在中断上下文里会跳过加锁，等于没有互斥。 */\n        vTaskDelay(pdMS_TO_TICKS(100));\n    }\n}\n\n/* ---------------- ⑥ 主程序上电顺序（调度器启动之前） ---------------- */\nvoid oled_app_start(void)\n{\n    /* 调度器还没跑，此时加锁是空操作；但先把总线拉起来，\n     * 任务里第一帧就不用再等总线初始化。 */\n    SYS_I2C_Init(OLED_I2C_ID, 400000);\n\n    if (oled_boot() != 0U) {\n        /* 上电先来一屏自检画面：四角点像素 + 一个方框 + 一行固定字符串。\n         * 以后任何显示异常，只要自检画面对，就说明驱动没问题、错在内容。 */\n        OLED_ClearBuffer();\n        OLED_DrawPoint(0, 0, 1);\n        OLED_DrawPoint(127, 0, 1);\n        OLED_DrawPoint(0, 63, 1);\n        OLED_DrawPoint(127, 63, 1);\n        OLED_DrawRect(0, 0, 127, 63, 1);\n        OLED_ShowStringCenter(28, \"OLED READY\", 0);\n        (void)OLED_Refresh();\n    }\n\n    /* 建显示任务。屏只该有一个“主人”，两个任务同时刷会互相踩显存。\n     * xTaskCreate(vOledTask, \"oled\", 256, 0, 3, 0); */\n}\n\n/* ---------------- ⑦ 板1（检测端）对照 ----------------\n *  同一块屏的另一套板级封装，函数名与形参不同，不可混用：\n *    SYS_I2C_Init(SYS_I2C_1, 400000);\n *    if (SYS_OLED_Init(SYS_I2C_1, SYS_OLED_I2C_ADDR) == 0U) { ... }\n *    SYS_OLED_Clear();                          // 清显存 + 立刻刷一次\n *    SYS_OLED_ShowString(0, 0, \"DETECT NODE-1\");   // 第一个参数是页号 0~7\n *    SYS_OLED_ShowFloat (2, 16, temp, 1);       // 保留 1 位小数\n *    SYS_OLED_ShowNum   (3, 32, (int32_t)cnt);  // 从 x 起按需占位\n *    SYS_OLED_SetPixel  (64, 32, 1);            // 像素坐标仍是 (x, y)\n *    if (SYS_OLED_Refresh() != 0U) { (void)SYS_OLED_ErrCount(); }\n *  两处最容易错的差异：\n *    ① 板1 的 ShowChar/ShowString/ShowNum/ShowFloat 第一个参数是页号 0~7，\n *       写成像素 y（比如 16）会被当成非法页，整行不显示；\n *    ② 板2 的同名函数多了 inv 参数（1 = 白底黑字反显），板1 没有反显入口；\n *       板1 的数字接口是从当前 x 按需占位，板2 的 ShowNum 带 len 定宽。\n *  两板驱动 .c 都整段持帧锁，缓冲与刷新语义一致，换板只改调用名。 */\n",
 r:"上电后屏先出现自检画面（四角各一个像素、一个整屏方框、中间一行 OLED READY），随后显示任务以 100ms 一帧刷新：第一行居中 NODE-2 COMM，下面 T=25.4 C、H=61.0 %、定宽 6 位计数器，底部一条 70% 进度条；用 OLED_ShowFixed / OLED_ShowNum 的定宽形式，数字位数变化时后面的内容不会被挤走，读数原地更新不跳动。连续跑十分钟应无残影、无半新半旧的撕裂、OLED_ErrCount() 保持 0；把 MPU6050 任务同时按 10ms 周期读数据加压仍然不撕裂，就是整帧锁在起作用，把 OLED_FRAME_LOCK() 临时去掉再跑一次，撕裂几乎必然出现，一对比就证明锁的价值。再故意把 0x8D,0x14 电荷泵那条注释掉重编：屏全黑，但 SYS_I2C_Scan 仍能扫到 0x3C、错误计数仍为 0，这就是“通信通、屏不亮”的典型，故障空间被一刀切成两半。",
 k:"SSD1306 OLED 128x64 0.96寸 I2C I2C1 PB8 PB9 0x3C 0x3D 0x78 SA0 控制字节 0x00 0x40 指令 显存数据 页寻址 页模式 页号 0xB0 低位在上 位序 1024 字节 帧缓冲 缓冲区 oled_buf 撕裂 半新半旧 递归互斥量 SYS_I2C_Lock SYS_I2C_Unlock OLED_FRAME_LOCK OLED_FRAME_UNLOCK 整帧持锁 40 次事务 23ms 20ms 400kHz 100kHz 脏页刷新 电荷泵 0x8D 0x14 0xAE 0xAF 0x20 0x81 0xCF 0xA1 0xC8 0xA6 对比度 初始化序列 OLED_Init OLED_IsOnline OLED_ErrCount OLED_LastErr OLED_ErrClear OLED_ClearBuffer OLED_Refresh OLED_Clear OLED_DisplayOn OLED_DisplayOff OLED_SetContrast OLED_DrawPoint OLED_GetPoint OLED_InvertScreen OLED_DrawHLine OLED_DrawVLine OLED_DrawLine OLED_DrawRect OLED_FillRect OLED_DrawCircle OLED_ShowProgress OLED_ShowChar OLED_ShowString OLED_ShowStringCenter OLED_ShowNum OLED_ShowFixed OLED_CHUNK OLED_RETRY SYS_OLED_Init SYS_OLED_Clear SYS_OLED_Refresh SYS_OLED_ShowChar SYS_OLED_ShowString SYS_OLED_ShowNum SYS_OLED_ShowFloat SYS_OLED_SetPixel SYS_OLED_ShowBitmap SYS_OLED_ErrCount SYS_OLED_LastErr SYS_OLED_DisplayOn SYS_OLED_DisplayOff SYS_I2C_Init SYS_I2C_Scan SYS_I2C_IsDeviceReady SYS_I2C_WriteBytes SYS_I2C_ERR_ADDR 上拉 4.7k 无调用者 main.c 显示任务 vTaskDelay 100ms 1ms 中断 SPI 版 SSD1306 相关"}"""
